import{z as E,x as A,o as s,c as p,q as o,j as l,D as r,d as n,s as t,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"后缀数组的应用","description":"","frontmatter":{"title":"后缀数组的应用","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/suffix-array-applications.md","filePath":"cs/suffix-array-applications.md","lastUpdated":1791413859000}'),B={name:"cs/suffix-array-applications.md"};function c(P,a,C,f,m,L){const i=A("Mermaid");return s(),p("div",null,[a[2]||(a[2]=o('<h1 id="后缀数组的应用" tabindex="-1">后缀数组的应用 <a class="header-anchor" href="#后缀数组的应用" aria-label="Permalink to &quot;后缀数组的应用&quot;">​</a></h1><div class="epigraph"><p>后缀排序加上 LCP，$O(1)$ 任意后缀对最长公共前缀；子串、重复、字典序区间都变成数组上的区间。</p><footer>—— 据 Manber and Myers, Suffix Arrays, 1993；Kasai 等 LCP 线性；Kärkkäinen–Sanders 线性 SA 整理</footer></div><p>上一课<a href="/cs/minimal-rotation">最小表示法</a>可以用 \\(s+s\\) 的最小后缀求循环同构。<a href="/cs/suffix-array">后缀数组</a>已给出构造，本课不重写倍增/SA-IS，缺口是<strong>应用</strong>：任意后缀对的 LCP、子串出现次数、最长重复子串、两串最长公共子串（拼接法）。后课 Lyndon。约定 <code>sa[i]</code> 是第 \\(i\\) 小后缀的起点，配合名次数组 <code>rk</code> 与相邻 LCP 数组 <code>lcp</code>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Kasai 算法 \\(O(n)\\) 求 <code>lcp[i]=LCP(sa[i],sa[i-1])</code>：按文本位置从大到小算，利用「文本位置减一的后缀，其 LCP 至少是当前值减一」从上次的值接着比，均摊线性。有了相邻 LCP，任意两后缀的 LCP 就是它们名次之间 <code>lcp</code> 的区间最小值，RMQ 预处理后 \\(O(1)\\) 回答。子串 \\(p\\) 的出现次数：所有以 \\(p\\) 为前缀的后缀在 SA 上是一段连续区间，区间端点用 LCP 比较二分或单调栈定出，区间长度即次数。最长重复子串：\\(\\max lcp\\)，取到最大处对应的后缀起点即答案。两串最长公共子串：拼接后取相邻两项来自不同串的 \\(lcp\\) 的最大值。</p><p><span class="marginnote">拿 \\(T=\\) <code>banana</code> 代一次：六个后缀排完得 \\(sa=[5,3,1,0,4,2]\\)。以 <code>ana</code> 开头的后缀是起点 3 和 1，恰占 SA 上连续一段（下标 1 到 2），区间长度 2 就是 <code>ana</code> 的出现次数——不用再逐个位置找。</span></p><p>缺口是把查询做出来，不是再排一遍后缀。</p><h3 id="不是后缀树课" tabindex="-1">不是后缀树课 <a class="header-anchor" href="#不是后缀树课" aria-label="Permalink to &quot;不是后缀树课&quot;">​</a></h3><p>后缀树能做同样的事，但空间与常数不同，本课全用数组。也不要把 SAM（后缀自动机）当 SA：自动机是另一套状态结构，转移语义与字典序名次无关。</p><p><span class="marginnote">Manber–Myers 1993。Kasai LCP。后课 Lyndon 分解与 SA/Duval 接口。正则爆炸本课序末。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程固定：构造 SA 与 LCP，RMQ 预处理，然后把具体题翻译成 SA 上的一段区间，或 LCP 直方图上的最大矩形（单调栈）。多串问题给各串加分隔符后拼接；分隔符必须互不相同且不出现在原串里，否则两串会在分隔处产生假的公共前缀。</p>',12)),(s(),l(d,null,{default:r(()=>[t(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SA%5B%22sa%20%2F%20rk%22%5D%20--%3E%20LCP%5B%22lcp%20%E6%95%B0%E7%BB%84%22%5D%0A%20%20LCP%20--%3E%20RMQ%5B%22%E5%90%8E%E7%BC%80%E5%AF%B9%20LCP%22%5D%0A%20%20LCP%20--%3E%20APP%5B%22%E9%87%8D%E5%A4%8D%20%2F%20%E5%87%BA%E7%8E%B0%E6%AC%A1%E6%95%B0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"机制核心：后缀排序把共享前缀的后缀排到相邻，共享多深由相邻 LCP 记录；不相邻两后缀的公共前缀不会超过区间内任何一段相邻 LCP，所以取区间 min。与 Z 函数对照：Z 给的是各后缀与全串的 LCP，SA+RMQ 给任意两后缀。与 KMP 对照：那是单模式匹配；SA 把所有子串装进一个结构，管的是统计。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"术语翻译：RMQ 就是「区间最小值查询」——给定数组和一堆询问 \\([l,r]\\)，每个询问返回这段里的最小值。用稀疏表 \\(O(n\\log n)\\) 预处理后每次 \\(O(1)\\)；这里最小化的对象是相邻 LCP。")],-1)),a[6]||(a[6]=e("p",null,"把「出现次数 = 区间长度」这条主用法的机制拆开看。",-1)),(s(),l(d,null,{default:r(()=>[t(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20P%5B%22%E6%A8%A1%E5%BC%8F%20P%22%5D%20--%3E%20SUF%5B%22%E4%BB%A5%20P%20%E4%B8%BA%E5%89%8D%E7%BC%80%E7%9A%84%E5%90%8E%E7%BC%80%E9%9B%86%E5%90%88%22%5D%0A%20%20SUF%20--%3E%20INT%5B%22%E5%9C%A8%20SA%20%E4%B8%8A%E6%98%AF%E4%B8%80%E6%AE%B5%E8%BF%9E%E7%BB%AD%E5%8C%BA%E9%97%B4%22%5D%0A%20%20INT%20--%3E%20L%5B%22%E4%BA%8C%E5%88%86%E5%AE%9A%E5%B7%A6%E7%AB%AF%E7%82%B9%22%5D%0A%20%20INT%20--%3E%20R%5B%22%E4%BA%8C%E5%88%86%E5%AE%9A%E5%8F%B3%E7%AB%AF%E7%82%B9%22%5D%0A%20%20L%20--%3E%20LEN%5B%22%E5%8C%BA%E9%97%B4%E9%95%BF%E5%BA%A6%20%3D%20%E5%87%BA%E7%8E%B0%E6%AC%A1%E6%95%B0%22%5D%0A%20%20R%20--%3E%20LEN%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">初学者容易以为求最长重复子串要枚举全部 \\(O(n^2)\\) 个子串再逐个验证，实际上它就是 \\(\\max lcp\\)：重复意味着两个后缀共享前缀，而共享前缀的深度已经被 LCP 数组逐段记录了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 SA-IS 的逐步证明，也不写压缩后缀数组的全文索引。后课默认：子串统计优先走 SA+LCP 这套。下一课 Lyndon 分解。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SA 加 LCP 加 RMQ，任意后缀 LCP 可 \\(O(1)\\) 回答。</li><li>最长重复与出现次数都落在 LCP 直方图上。</li><li>构造当黑盒，本课只消费查询。</li><li>出处：Manber and Myers, 1993；Kasai 等。</li></ul>',5))])}const h=E(B,[["render",c]]);export{S as __pageData,h as default};
